{
  "name": "Daily hand-forwarding of the Credit Report",
  "today": "Credit (Veronica Espinoza, Russell Diamond) emails a 'Credit Report' every business day to a list of about 35 people. The list includes desk lead Darron Giron but not the staff who rebook the deals it names (Carole Frank, later Ryan O'Rourke). Giron forwards each report to them, usually with no comment. When he is away the reports are not passed on: on 19 March he forwarded the 12 March report a week late, saying he didn't know if she had received any while he was out. That report listed deals to rebook.",
  "change": "Ask Credit to add the desk's rebook person to the Credit Report list so Giron no longer forwards it every day.",
  "explanation": "Credit adds Carole Frank (or whoever does the rebooks, or a desk group mailbox) to the Credit Report list. This is a one-time edit. Giron stays on the list. After that the report goes straight to the person who does the rebooks, there is nothing to forward each day, and rebooks are not held up while Giron is out.",
  "occurrences": [
    {"file": "corpus/giron-d/sent/189.eml", "quote": "Forwarded by Darron C Giron/HOU/ECT on 02/27/2001"},
    {"file": "corpus/giron-d/sent/154.eml", "quote": "I don't know if you got any of these while I was out."}
  ],
  "evidence": [
    {"file": "corpus/giron-d/sent/189.eml", "quote": "From: Veronica Espinoza/ENRON@enronXgate on 02/27/2001 10:22 AM", "note": "Credit sends the report itself to a list that includes Giron but not Carole Frank. He forwards it two minutes later with nothing added, so the forward only gets the report to the right person."},
    {"file": "corpus/giron-d/sent/154.eml", "quote": "Rebook to CMS Marketing, Services and", "note": "The report lists deals for the desk to rebook. While Giron was out, the 12 March report reached the rebooker only on 19 March."},
    {"file": "corpus/giron-d/sent/154.eml", "quote": "From: Russell Diamond/ENRON@enronXgate on 03/12/2001 09:03 AM", "note": "The report Giron forwarded on 19 March was sent by Credit a week earlier."}
  ],
  "ongoing": true,
  "stated_rate": null,
  "minutes": 2
}

{
  "name": "Hourly generator checkout calls to BPA (Grays Harbor and Frontier)",
  "today": "Every hour, day and night, a Portland real-time trader phones the Grays Harbor and Frontier generators for the actual energy produced, phones BPA with that number, and initials the hour in the services book. This is done even when the generator's output was scheduled in advance. It depends on a busy trader remembering, and calls were being missed: BPA complained about 'inconsistent performance' and threatened to recommend that Enron could not provide the service.",
  "change": "Meter the two generators automatically so their hourly output goes to BPA without a trader phoning it in.",
  "explanation": "Work with BPA and the generator owners to put Grays Harbor and Frontier on automatic metering, which the desk manager names as the point when the calls can stop. Hourly output data would then reach BPA, and the services sheet, electronically. Traders would no longer make the three hourly steps (call the generator, call BPA, initial the sheet). They would act only when a meter fails or reserves are used. BPA would get its numbers every hour whether or not the desk is busy, which addresses its complaint. The one-time cost of the metering is not counted here.",
  "occurrences": [
    {
      "file": "corpus/williams-w3/sent_items/357.eml",
      "quote": "We must call Grays Harbor and Frontier at the top of EVERY hour.  Then we need to call BPA and communicate the ACTUAL energy generated, not an estimate.  Finally, sign off the hour in the services book."
    },
    {
      "file": "corpus/williams-w3/sent_items/506.eml",
      "quote": "We must check out with BPA each hour for Frontier and GCPUD."
    }
  ],
  "evidence": [
    {
      "file": "corpus/williams-w3/sent_items/357.eml",
      "quote": "If this process takes more than 5 minutes, please let me know.",
      "note": "The manager expects each hourly checkout to take under 5 minutes of a trader's time."
    },
    {
      "file": "corpus/williams-w3/sent_items/357.eml",
      "quote": "we need to do this even if the generator is prescheduled, and must to continue to do this until these generators are automatically metered.",
      "note": "The calls are made even when the output is already known, and the manager names automatic metering as what would end them."
    },
    {
      "file": "corpus/williams-w3/sent_items/357.eml",
      "quote": "Warren is inclined to recommend to BPA that we are incapable of this service because of our inconsistent performance.",
      "note": "Where it stalls: busy traders miss or delay the manual calls, which puts the service at risk."
    },
    {
      "file": "corpus/williams-w3/sent_items/506.eml",
      "quote": "The new service sheets have a place for initials for the call each hour, please initial after making the call to BPA (ext. 2277).",
      "note": "The step of initialing the sheet after each call, which automatic data would remove."
    }
  ],
  "ongoing": true,
  "stated_rate": {
    "count": 24,
    "per": "day",
    "file": "corpus/williams-w3/sent_items/357.eml",
    "quote": "at the top of EVERY hour"
  },
  "minutes": 3
}

