{
  "name": "Weekly manual compaction of WeaponX",
  "today": "WeaponX is an Access database. Each gas book admin keeps their own copy of the file. It imports and deletes a lot of data every day, and Access does not free the space when data is deleted, so the file keeps growing. One Texas file had reached 520 MB and one West file 400 MB. On 13 Oct 2000 Greg Couch asked six desk leads to have every book admin compact the file by hand at least once a week: open it while holding the shift key, choose Tools/Database Utilities/Compact Database, wait for it to finish, then use it as normal. One admin (Crystal) already did this every day. The step relies on each admin remembering to do it, and the instruction itself had to be passed along by hand (Giron forwarded it to Anne Bike twice, on 13 and 17 Oct).",
  "change": "Turn on Access's automatic compaction for WeaponX so book admins no longer compact it by hand each week.",
  "explanation": "Whoever maintains WeaponX switches on the Access option that compacts the file automatically when it is closed (Tools/Options, 'Compact on Close', in Access 2000 and later), or adds a compact step at the end of the daily run. The fixed file goes out the same way a new copy was sent in Jan 2002, through a shared Dropbox folder. After that the file stays small without anyone acting, admins skip the shift-key open and the compact, and nobody has to send or forward reminders.",
  "occurrences": [
    {"file": "corpus/giron-d/sent/596.eml", "quote": "I would like each of your book admins using WeaponX to begin using the \nfollowing procedures at least once/week (if they aren't already)."},
    {"file": "corpus/giron-d/sent/585.eml", "quote": "Try this and see if it does any good."}
  ],
  "evidence": [
    {"file": "corpus/giron-d/sent/596.eml", "quote": "Open the database while holding down on the shift key.", "note": "The manual steps every admin must do each week: a special open, then the menu compact, then a normal reopen."},
    {"file": "corpus/giron-d/sent/596.eml", "quote": "WeaponX imports and deletes \na lot of data on a daily basis.", "note": "The cause is built into the daily work, so the need to compact never ends. That makes it a good job to automate."},
    {"file": "corpus/giron-d/sent/596.eml", "quote": "The Texas WeaponX file that I compacted reduced from 520 MB to 30 MB and one \nfor the west went from 400 MB to 12 MB.", "note": "Shows how much the files grow when admins forget or skip the step."},
    {"file": "corpus/giron-d/sent/596.eml", "quote": "Crystal (East desk I believe) already compacts the database on a daily \nbasis.", "note": "At least one admin does this every day, so the weekly figure is a low estimate."},
    {"file": "corpus/giron-d/inbox/128.eml", "quote": "A healthy, functional Weapon X has been saved out in the O\\Dropbox\\Kam folder.  Please save this to your own hard drive and help distribute it.", "note": "A new copy of the file has been sent to the admins this way before, so one copy with the setting turned on can reach everyone."}
  ],
  "ongoing": true,
  "stated_rate": {"count": 1, "per": "week", "file": "corpus/giron-d/sent/596.eml", "quote": "at least once/week"},
  "minutes": 24
}

{
  "name": "Counterparty MTM valuations for auditors",
  "today": "Counterparties' auditors ask Enron for third-party mark-to-market (MTM) values and open positions as of a past date, usually a year-end. Confirmations (Joe Hunter, Ellen Wallumrod) answers these requests but has no system that values deals. So each request goes by email to five or six gas desk heads (Gossett, Keiser, Love, Giron, McLaughlin, Baumbach). Each head forwards it to a book administrator on the desk (Giron, for example, forwards to Pat Ryder or Carole Frank). That person runs a mini-book for the counterparty as of the past date, blacks out the Delta/Vol columns, exports it to Excel and emails it back. Confirmations waits on several desks and then puts the answers together. Hunter says requests come in several times a week.",
  "change": "Give Confirmations a report that shows any counterparty's MTM as of a past month-end, so the desks no longer run and redact a mini-book for each auditor request.",
  "explanation": "Build the tool Hunter's email already names: EnTelligence, or a scheduled extract from the risk system, that keeps month-end curves and shows MTM and open position by counterparty short name as of any past month-end, with the Delta/Vol columns left out. Confirmations staff would run it themselves when an auditor request comes in and send the result straight to the counterparty. The emails to the desk heads, their forwards, the mini-book runs on each desk, the blacking out of Delta/Vol and the Excel exports would all stop.",
  "occurrences": [
    {
      "file": "corpus/giron-d/sent/240.eml",
      "quote": "Please forward to Ellen Wallumrod the MTM valuation(mini-book) for all \nCoEnergy Trading Company deals as of Dec 31, 2000."
    },
    {
      "file": "corpus/giron-d/sent/214.eml",
      "quote": "Can you provide MTM values as of Dec 29, 2000, for the short name of CROSS \nTIMBERS."
    },
    {
      "file": "corpus/giron-d/sent/137.eml",
      "quote": "Two more counterparties need MTM values for Dec. 29, 2000."
    }
  ],
  "evidence": [
    {
      "file": "corpus/giron-d/sent/241.eml",
      "quote": "We do not have access to \nany system that values these deals, but are looking to get the on-line \n\"EnTelligence\" built so that it carries back-dated curves that will allow us \nto complete these requests without taking up a Risk person's time and without \nhaving to black out information (Delta/Vol) that is included in a mini-book.",
      "note": "Confirmations cannot value deals itself, so every request takes Risk staff time and a manual redaction step. The proposed report removes both."
    },
    {
      "file": "corpus/giron-d/sent/241.eml",
      "quote": "Until we can get EnTelligence built to our specifications, \nwe'll need to continue to go to the different desks to provide Mark-to-Market \nvaluations for a Counterparty's portfolio.",
      "note": "Each request goes to several desks, not just one."
    },
    {
      "file": "corpus/giron-d/sent/240.eml",
      "quote": "If you can export into \nexcel and forward by e-mail, that would be appreciated.",
      "note": "The desk runs the mini-book, exports it and emails it back by hand."
    },
    {
      "file": "corpus/giron-d/sent/137.eml",
      "quote": "Please provide the total MTM value for that date within your region.",
      "note": "The request goes to every region's desk and each one answers separately, so Confirmations has to wait for and combine several replies."
    },
    {
      "file": "corpus/giron-d/sent/136.eml",
      "quote": "The following are the totals for Tudor BVI and Ospraie.  The total MTM value \nfor the West Desk are as follows.  Detail can be found in the attachment.",
      "note": "A West desk book admin (Carole Frank) did the run and sent it back up through Giron, showing the forwarding chain."
    }
  ],
  "ongoing": true,
  "stated_rate": {
    "count": 3,
    "per": "week",
    "file": "corpus/giron-d/sent/241.eml",
    "quote": "we recieve several \nper week"
  },
  "minutes": 40
}

